package services.economy.tables.roomPlacement
import cats.effect.IO
import java.sql.Connection
import services.system.tables.Jdbc
object RoomPlacementTableInitializer:
  private val initializeSql = """CREATE TABLE IF NOT EXISTS room_placements(user_id text NOT NULL REFERENCES users(id),slot text NOT NULL,item_id text REFERENCES player_items(id),reward_id text REFERENCES task_rewards(id),x integer NOT NULL DEFAULT 50,y integer NOT NULL DEFAULT 50,PRIMARY KEY(user_id,slot),CHECK((item_id IS NULL)<>(reward_id IS NULL))); ALTER TABLE room_placements ADD COLUMN IF NOT EXISTS x integer NOT NULL DEFAULT 50; ALTER TABLE room_placements ADD COLUMN IF NOT EXISTS y integer NOT NULL DEFAULT 50; UPDATE room_placements SET x=27,y=43 WHERE slot='window' AND x=50 AND y=50; UPDATE room_placements SET x=66,y=28 WHERE slot='wall' AND x=50 AND y=50; UPDATE room_placements SET x=81,y=53 WHERE slot='lighting' AND x=50 AND y=50; UPDATE room_placements SET x=64,y=65 WHERE slot='desk' AND x=50 AND y=50; UPDATE room_placements SET x=53,y=78 WHERE slot='chair' AND x=50 AND y=50; UPDATE room_placements SET x=75,y=85 WHERE slot='floor' AND x=50 AND y=50; CREATE UNIQUE INDEX IF NOT EXISTS placed_item_unique ON room_placements(item_id) WHERE item_id IS NOT NULL; CREATE UNIQUE INDEX IF NOT EXISTS placed_reward_unique ON room_placements(reward_id) WHERE reward_id IS NOT NULL;"""
  def initialize(connection: Connection): IO[Unit] = Jdbc.initialize(connection,initializeSql)
